import fs from'node:fs';import path from'node:path';import{performance}from'node:perf_hooks';import{openSettlementPortfolioHostV2}from'../live-paper/settlement-portfolio-host-v2.mjs';
const rt=path.join(process.env.LOCALAPPDATA,'SigTradingCup/paper-runtime'),e=JSON.parse(fs.readFileSync('data/settlement-portfolio-prepared-20261005-v2.json')),bank=JSON.parse(fs.readFileSync(path.join(rt,'settlement-portfolio-v2-cohorts',e.cohort,'bank.json'))),start=performance.now();let host;
